 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    midr, midc = h // 2, w // 2
    seed = [row[:midc] for row in grid[:midr]]
    out = [row[:] for row in grid]
    for r in range(h):
        if r == midr:
            continue
        ir = r if r < midr else r - midr - 1
        for c in range(w):
            if c == midc:
                continue
            ic = c if c < midc else c - midc - 1
            out[r][c] = seed[ir][ic]
    return out
